/**
 * 乘务员资质主记录。
 *
 * @param id                主键
 * @param crewId            乘务员 id
 * @param qualificationCode 资质代码，同一乘务员内唯一
 * @param role              资质适用角色
 * @param expiresAtUtc      到期时刻（UTC），须严格晚于计划终到时刻方为有效
 * @param terminated        是否已提前终止
 * @param version           资质版本，每次修改加一，修改/终止须携带 expectedVersion
 */
public record Qualification(long id, String crewId, String qualificationCode, CrewRole role,
                            Instant expiresAtUtc, boolean terminated, int version) {
}

package com.example.starter.plan.model;

import java.time.Instant;

/**
 * 不可变乘务资质风险记录。资质被提前终止时，对每个受影响的未来已发布计划写入一条；
 * 计划不会被自动取消，而是进入风险门禁状态等待两角色均替换为合格人员。
 *
 * @param id                主键
 * @param planId            受影响计划 id
 * @param crewId            涉及乘务员 id
 * @param role              涉及角色
 * @param qualificationCode 被提前终止的资质代码
 * @param reason            风险原因代码
 * @param createdAtUtc      记录创建时刻（UTC）
 */
public record RiskRecord(long id, long planId, String crewId, CrewRole role,
                         String qualificationCode, String reason, Instant createdAtUtc) {
}

package com.example.starter.plan.model;

import java.time.LocalDate;

/**
 * 铁路走廊日计划主记录。
 *
 * @param id          主键
 * @param scheduleKey 计划业务键，全局唯一
 * @param opDate      运营日期（Asia/Shanghai 日历日）
 * @param version     版本号，草稿占用整体替换成功一次加一
 * @param status      计划状态
 * @param driverId    司机乘务员 id，发布/改签时指定，{@code null} 表示未指定乘务
 * @param conductorId 车长乘务员 id，发布/改签时指定，{@code null} 表示未指定乘务
 * @param riskBlocked 乘务风险门禁：true 表示资质被提前终止，禁止普通改签与同车底新增段发布
 */
public record DayPlan(long id, String scheduleKey, LocalDate opDate, int version, PlanStatus status,
                      String driverId, String conductorId, boolean riskBlocked) {
}

